parameters.jsonBody:
={{ ({
  model: 'gpt-5-mini',
  store: true,
  input: [
    {
      role: 'developer',
      content: $json.classification_instructions
    },
    {
      role: 'user',
      content: $json.reply_input
    }
  ],
  text: {
    format: {
      type: 'json_schema',
      name: 'lead_intent_classification',
      strict: true,
      schema: {
        type: 'object',
        properties: {
          category: {
            type: 'string',
            description: 'Intent classification for the lead.',
            enum: ['OOO', 'Interested', 'NRR', 'Spam_Inbound', 'Left_Company', 'other']
          },
          confidence: {
            type: 'number',
            description: "Model's confidence in the classification (0-100).",
            minimum: 0,
            maximum: 100
          },
          short_reason: {
            type: 'string',
            description: 'Very short explanation (1 sentence max) of why this category was chosen.',
            minLength: 1,
            maxLength: 200
          },
          language_detected: {
            type: 'string',
            description: 'Top-level detected language code for the message.',
            enum: ['pl', 'en', 'de', 'other']
          }
        },
        required: ['category', 'confidence', 'short_reason', 'language_detected'],
        additionalProperties: false
      }
    }
  }
}) }}
